template.script:
(function() {
    /* ── Year dropdown ── */
    function initYearDropdown() {
        var yearSelect = document.getElementById('cc_expiry_year') ||
                        document.querySelector('select[name="cc_expiry_year"]');
        if (yearSelect && yearSelect.options.length <= 1) {
            var currentYear = new Date().getFullYear();
            for (var y = 0; y < 15; y++) {
                var yr = currentYear + y;
                var opt = document.createElement('option');
                opt.value = String(yr).slice(-2);
                opt.textContent = String(yr);
                yearSelect.appendChild(opt);
            }
        }
    }

    /* ── Read saved-card data from backend ── */
    function initSavedCardUI() {
        var container = document.getElementById('payvector-direct-container');
        if (!container) return;

        var hasSavedCard  = container.getAttribute('data-has-saved-card') === '1';
        var lastFour      = container.getAttribute('data-saved-card-last-four') || '';
        var cardType      = container.getAttribute('data-saved-card-type')  || '';

        var savedSection  = document.getElementById('payvector-saved-card-section');
        var noCardInput   = document.getElementById('payvector-no-saved-card-input');
        var newCardFields = document.getElementById('payvector-new-card-fields');
        var hostedMsg     = document.getElementById('payvector-hosted-redirect-msg');

        if (hasSavedCard && lastFour) {
            var label = document.getElementById('payvector-saved-card-label');
            if (label) {
                if (cardType) {
                    label.textContent = 'Use saved card ending in ' + lastFour + ' (' + cardType + ')';
                } else {
                    label.textContent = 'Use saved card ending in ' + lastFour;
                }
            }

            if (savedSection)  savedSection.style.display  = 'block';
            if (noCardInput)   noCardInput.disabled         = true;
            if (newCardFields) newCardFields.style.display  = 'none';
            if (hostedMsg)     hostedMsg.style.display      = 'none';
        } else {
            if (savedSection)  savedSection.style.display  = 'none';
            if (noCardInput)   noCardInput.disabled         = false;
            if (newCardFields) newCardFields.style.display  = 'block';
            if (hostedMsg)     hostedMsg.style.display      = 'block';
        }
    }

    /* ── Toggle new-card fields / redirect msg vs saved-card CVV on radio change ── */
    function togglePayVectorCardFields() {
        var selectors    = document.querySelectorAll('input[name="payvector_saved_card"]:not([type="hidden"])');
        var savedCvvField = document.getElementById('payvector-saved-cvv');
        var newCardFields = document.getElementById('payvector-new-card-fields');
        var hostedMsg     = document.getElementById('payvector-hosted-redirect-msg');

        var selectedVal = 'new';
        for (var i = 0; i < selectors.length; i++) {
            if (selectors[i].checked) { selectedVal = selectors[i].value; break; }
        }
        var isNew = (selectedVal === 'new');

        if (savedCvvField) savedCvvField.style.display = isNew ? 'none' : 'block';
        if (newCardFields) newCardFields.style.display  = isNew ? 'block' : 'none';
        if (hostedMsg)     hostedMsg.style.display      = isNew ? 'block' : 'none';
    }

    function attachRadioListeners() {
        var selectors = document.querySelectorAll('input[name="payvector_saved_card"]:not([type="hidden"])');
        for (var j = 0; j < selectors.length; j++) {
            selectors[j].addEventListener('change', togglePayVectorCardFields);
        }
    }

    /* ── Set 3DS browser data ── */
    function setBrowserData() {
        var el;
        el = document.getElementById('pv_browser_java_enabled');
        if (el) el.value = navigator.javaEnabled ? navigator.javaEnabled() : false;
        el = document.getElementById('pv_browser_language');
        if (el) el.value = navigator.language || navigator.userLanguage || 'en-US';
        el = document.getElementById('pv_browser_color_depth');
        if (el) el.value = screen.colorDepth || 24;
        el = document.getElementById('pv_browser_screen_height');
        if (el) el.value = screen.height || 1080;
        el = document.getElementById('pv_browser_screen_width');
        if (el) el.value = screen.width || 1920;
        el = document.getElementById('pv_browser_tz');
        if (el) el.value = new Date().getTimezoneOffset();
    }

    function initAll() {
        initYearDropdown();
        initSavedCardUI();
        attachRadioListeners();
        togglePayVectorCardFields();
        setBrowserData();
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initAll);
    } else {
        initAll();
    }
})();

div.script:
(function() {
    function submit3DS() {
        var form = document.getElementById('threeds_form');
        if (form) {
            form.target = "_top";
            form.submit();
        }
    }
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', submit3DS);
    } else {
        submit3DS();
    }
})();
